Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Explore enzyme specificity</span>
<label><input id="bindingModelInput" type="checkbox" onchange="toggle_bindingModel(this.checked)"> Binding model: induced fit</label>
<button onclick="trigger_bindingAnimation()">Animate substrate binding</button>
<span id="demoNarration" style="display:block;margin:4px 0 0 0;font-size:10px;line-height:1.35;max-width:260px"></span>
<span style="display:block"><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1000, H = 430;
draw.viewbox(0, 0, W, H);

var figState = {
  model: 'lock',
  progress: 0,
  step: 0,
  animating: false
};

var demoSteps = [
  {
    title: 'Rigid fit',
    narration: 'In the lock-and-key model, the enzyme already has an active site with the proper shape. When the substrates move into place, the active-site geometry stays essentially unchanged.',
    state: { bindingModel: 'Lock-and-key' }
  },
  {
    title: 'Adaptive fit',
    narration: 'In the induced-fit model, the active site begins more open and changes shape as the substrate approaches. The bound complex forms only after the enzyme reshapes around the substrate.',
    state: { bindingModel: 'Induced fit' }
  },
  {
    title: 'Compare the mechanisms',
    narration: 'Both models explain why only compatible substrates bind, but they locate the specificity in different places: a fixed pocket for lock-and-key, and a conformational adjustment for induced fit.',
    state: { bindingModel: 'Lock-and-key' }
  }
];

var colors = {
  enzyme: '#dfe9c8',
  enzymeLight: '#eef3d8',
  enzymeEdge: '#7c9b3e',
  purple: '#d7c4e1',
  purpleLight: '#eadff0',
  peg: '#d7aa86',
  black: '#111111',
  text: '#222222'
};

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function pstr(x, y) {
  return x.toFixed(1) + ',' + y.toFixed(1);
}

function enzymePath(cx, y, model, prog) {
  if (model === 'lock') {
    return [
      'M', pstr(cx - 185, y + 10),
      'C', pstr(cx - 178, y - 32), pstr(cx - 132, y - 58), pstr(cx - 99, y - 40),
      'C', pstr(cx - 77, y - 27), pstr(cx - 88, y + 2), pstr(cx - 70, y + 6),
      'C', pstr(cx - 55, y + 9), pstr(cx - 52, y - 12), pstr(cx - 48, y - 36),
      'L', pstr(cx - 39, y - 88),
      'L', pstr(cx - 27, y - 35),
      'C', pstr(cx - 22, y - 9), pstr(cx - 8, y + 10), pstr(cx + 2, y + 4),
      'C', pstr(cx + 11, y - 1), pstr(cx + 11, y - 35), pstr(cx + 17, y - 88),
      'L', pstr(cx + 29, y - 35),
      'C', pstr(cx + 35, y - 8), pstr(cx + 44, y + 10), pstr(cx + 58, y + 5),
      'C', pstr(cx + 74, y), pstr(cx + 66, y - 28), pstr(cx + 91, y - 42),
      'C', pstr(cx + 123, y - 60), pstr(cx + 180, y - 31), pstr(cx + 185, y + 10),
      'C', pstr(cx + 193, y + 70), pstr(cx + 114, y + 96), pstr(cx, y + 97),
      'C', pstr(cx - 114, y + 96), pstr(cx - 193, y + 70), pstr(cx - 185, y + 10),
      'Z'
    ].join(' ');
  }

  var a = Math.max(0, Math.min(1, prog));
  return [
    'M', pstr(cx - 185, y + 10),
    'C', pstr(cx - 178, y - 31), pstr(cx - 132, y - 58), pstr(cx - 100, y - 41),
    'C', pstr(cx - 82, y - 31 - 5 * a), pstr(cx - 77, y - 7 - 20 * a), pstr(cx - 63, y - 4 - 4 * a),
    'C', pstr(cx - 47, y - 1 - 11 * a), pstr(cx - 43, y - 28 - 38 * a), pstr(cx - 37, y - 36 - 48 * a),
    'C', pstr(cx - 30, y - 50 - 22 * a), pstr(cx - 18, y - 25 - 36 * a), pstr(cx - 7, y - 23 - 32 * a),
    'C', pstr(cx, y - 20 - 31 * a), pstr(cx + 7, y - 20 - 31 * a), pstr(cx + 14, y - 23 - 32 * a),
    'C', pstr(cx + 25, y - 25 - 36 * a), pstr(cx + 34, y - 50 - 22 * a), pstr(cx + 42, y - 36 - 48 * a),
    'C', pstr(cx + 49, y - 27 - 38 * a), pstr(cx + 52, y - 1 - 11 * a), pstr(cx + 66, y - 4 - 4 * a),
    'C', pstr(cx + 81, y - 8 - 20 * a), pstr(cx + 84, y - 31 - 5 * a), pstr(cx + 104, y - 42),
    'C', pstr(cx + 127, y - 55), pstr(cx + 181, y - 29), pstr(cx + 185, y + 10),
    'C', pstr(cx + 193, y + 70), pstr(cx + 114, y + 96), pstr(cx, y + 97),
    'C', pstr(cx - 114, y + 96), pstr(cx - 193, y + 70), pstr(cx - 185, y + 10),
    'Z'
  ].join(' ');
}

function makeArrowMarker() {
  var marker = draw.marker(9, 9, function (add) {
    add.path('M 0 0 L 9 4.5 L 0 9 z').fill(colors.black);
  });
  marker.ref(8.2, 4.5).orient('auto');
  return marker;
}

function addArrowPath(d, marker, width) {
  return draw.path(d).fill('none').stroke({ color: colors.black, width: width || 2.2, linecap: 'round', linejoin: 'round' }).attr({ 'marker-end': marker.url() });
}

function addLeader(x1, y1, x2, y2) {
  return draw.line(x1, y1, x2, y2).stroke({ color: colors.black, width: 2.2, linecap: 'round' });
}

function textBlock(lines, x, y, size, anchor) {
  if (typeof lines === 'string') lines = lines.split('\n');
  anchor = anchor || 'middle';
  var g = draw.group();
  var lineH = size * 1.12;
  for (var i = 0; i < lines.length; i++) {
    var t = g.text(lines[i]).font({
      family: 'Arial, Helvetica, sans-serif',
      size: size,
      anchor: anchor
    }).fill(colors.text).attr({
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    });
    if (anchor === 'middle') {
      t.center(x, y + i * lineH);
    } else if (anchor === 'end') {
      t.move(x - t.bbox().width, y + i * lineH - size * 0.55);
    } else {
      t.move(x, y + i * lineH - size * 0.55);
    }
  }
  return g;
}

function drawEnzyme(cx, y, model, prog, label) {
  var g = draw.group();
  var body = g.path(enzymePath(cx, y, model, prog))
    .fill(colors.enzyme)
    .stroke({ color: colors.black, width: 3.3, linejoin: 'round' });

  g.path([
    'M', pstr(cx - 146, y + 22),
    'C', pstr(cx - 112, y + 70), pstr(cx - 48, y + 79), pstr(cx, y + 79),
    'C', pstr(cx + 52, y + 79), pstr(cx + 115, y + 69), pstr(cx + 146, y + 22),
    'C', pstr(cx + 97, y + 105), pstr(cx - 96, y + 105), pstr(cx - 146, y + 22),
    'Z'
  ].join(' ')).fill(colors.enzymeLight).stroke('none').opacity(0.88);

  body.on('mousemove', function (e) {
    showTooltip(label, e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup('Enzyme active site', model === 'lock'
      ? 'In the lock-and-key model, the pocket is drawn with the same geometry before and after binding. Specificity comes from this pre-existing complementarity.'
      : 'In the induced-fit model, the pocket starts open and flexible. Binding changes the enzyme conformation so the active site wraps more closely around the substrate.');
  }).css('cursor', 'pointer');
  return g;
}

function drawSubstrate(cx, cy, side, scale, tooltip) {
  var s = side === 'right' ? -1 : 1;
  scale = scale || 1;
  var g = draw.group();

  function X(x) { return cx + s * x * scale; }
  function Y(y) { return cy + y * scale; }

  var pegX = cx + s * 18 * scale - 10 * scale;
  g.rect(20 * scale, 31 * scale).radius(6 * scale)
    .move(pegX, Y(82))
    .fill(colors.peg)
    .stroke({ color: '#ad8467', width: 1.3 * scale });

  var d = [
    'M', pstr(X(30), Y(90)),
    'L', pstr(X(10), Y(90)),
    'L', pstr(X(10), Y(72)),
    'C', pstr(X(-13), Y(75)), pstr(X(-34), Y(62)), pstr(X(-34), Y(43)),
    'C', pstr(X(-35), Y(19)), pstr(X(-10), Y(0)), pstr(X(16), Y(0)),
    'C', pstr(X(39), Y(0)), pstr(X(56), Y(18)), pstr(X(52), Y(37)),
    'C', pstr(X(50), Y(52)), pstr(X(40), Y(61)), pstr(X(30), Y(67)),
    'Z'
  ].join(' ');

  var blob = g.path(d)
    .fill(colors.purple)
    .stroke({ color: colors.black, width: 3 * scale, linejoin: 'round' });

  var hi = [
    'M', pstr(X(16), Y(13)),
    'C', pstr(X(35), Y(13)), pstr(X(47), Y(28)), pstr(X(41), Y(43)),
    'C', pstr(X(33), Y(60)), pstr(X(14), Y(56)), pstr(X(16), Y(76)),
    'L', pstr(X(19), Y(84)),
    'L', pstr(X(15), Y(84)),
    'C', pstr(X(8), Y(57)), pstr(X(-13), Y(66)), pstr(X(-20), Y(49)),
    'C', pstr(X(-28), Y(28)), pstr(X(-6), Y(13)), pstr(X(16), Y(13)),
    'Z'
  ].join(' ');
  g.path(hi).fill(colors.purpleLight).stroke('none').opacity(0.75);

  blob.on('mousemove', function (e) {
    showTooltip(tooltip || 'Substrate piece', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup('Substrate', 'Only substrates with compatible shape and chemistry form the enzyme-substrate complex. The two purple pieces represent substrates approaching and occupying the active site.');
  }).css('cursor', 'pointer');

  return g;
}

function drawSubstratePair(cx, topY, spread, scale, tooltip) {
  var g = draw.group();
  g.add(drawSubstrate(cx - spread, topY, 'left', scale, tooltip));
  g.add(drawSubstrate(cx + spread, topY, 'right', scale, tooltip));
  return g;
}

function drawScene() {
  draw.clear();
  var marker = makeArrowMarker();
  var model = figState.model;
  var p = figState.progress;
  var isLock = model === 'lock';
  var modelTitle = isLock ? '(a) Lock-and-key model' : '(b) Induced fit model';
  var activeLabel = isLock ? 'Active\nsite is\nproper\nshape' : 'Active\nsite\nchanges\nto fit';

  var leftCx = 270, rightCx = 735, enzymeY = 270;
  var startSpread = 80, endSpread = 36;
  var startTop = 76, endTop = 152;
  var movingTop = lerp(startTop, endTop, p);
  var movingSpread = lerp(startSpread, endSpread, p);
  var leftShapeProgress = isLock ? 0 : p;

  drawEnzyme(leftCx, enzymeY, model, leftShapeProgress, isLock ? 'Rigid pre-formed active-site cavity' : 'Flexible active-site cavity');
  drawEnzyme(rightCx, enzymeY, model, 1, isLock ? 'Unchanged enzyme-substrate complex' : 'Reshaped induced-fit complex');

  drawSubstratePair(leftCx, movingTop, movingSpread, 1, 'Substrates moving toward the active site');
  drawSubstratePair(rightCx, endTop, endSpread, 1, 'Substrates seated in the active site');

  addLeader(leftCx - 72, 34, leftCx - 103, startTop + 22);
  addLeader(leftCx + 72, 34, leftCx + 103, startTop + 22);

  addArrowPath('M ' + (leftCx - 118) + ' ' + (startTop + 104) + ' C ' + (leftCx - 70) + ' ' + (startTop + 110) + ' ' + (leftCx - 78) + ' ' + (enzymeY - 48) + ' ' + (leftCx - 49) + ' ' + (enzymeY - 37), marker, 2);
  addArrowPath('M ' + (leftCx + 118) + ' ' + (startTop + 104) + ' C ' + (leftCx + 70) + ' ' + (startTop + 110) + ' ' + (leftCx + 78) + ' ' + (enzymeY - 48) + ' ' + (leftCx + 49) + ' ' + (enzymeY - 37), marker, 2);

  addArrowPath('M ' + (leftCx - 34) + ' 170 L ' + (leftCx - 48) + ' ' + (enzymeY - 72), marker, 2.2);
  addArrowPath('M ' + (leftCx + 34) + ' 170 L ' + (leftCx + 48) + ' ' + (enzymeY - 72), marker, 2.2);

  textBlock('Substrates', leftCx, 18, 28, 'middle');
  textBlock(activeLabel, leftCx, 78, 27, 'middle');
  textBlock('Substrate\ncomplex\nformed', rightCx, 68, 27, 'middle');
  textBlock('Enzyme', leftCx, 370, 27, 'middle');
  textBlock('Enzyme', rightCx, 370, 27, 'middle');
  textBlock(modelTitle, 500, 412, 26, 'middle');

  var noteDot = draw.circle(10).center(isLock ? leftCx - 42 : leftCx, enzymeY - 78).fill('#ffffff').stroke({ color: colors.black, width: 1.5 }).opacity(0.85);
  noteDot.on('mousemove', function (e) {
    showTooltip(isLock ? 'The cavity is already complementary before binding.' : 'The cavity changes shape as binding progresses.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).css('cursor', 'pointer');
}

function setModelFromName(name) {
  figState.model = name === 'Induced fit' ? 'induced' : 'lock';
  figState.progress = 0;
  var cb = document.getElementById('bindingModelInput');
  if (cb) cb.checked = figState.model === 'induced';
  drawScene();
}

function toggle_bindingModel(on) {
  figState.model = on ? 'induced' : 'lock';
  figState.progress = 0;
  drawScene();
}

function trigger_bindingAnimation() {
  if (figState.animating) return;
  figState.animating = true;
  var t0 = performance.now();
  var dur = figState.model === 'induced' ? 1450 : 1100;

  function ease(t) {
    return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
  }

  function frame(now) {
    var raw = Math.min(1, (now - t0) / dur);
    figState.progress = ease(raw);
    drawScene();
    if (raw < 1) {
      requestAnimationFrame(frame);
    } else {
      figState.animating = false;
    }
  }
  requestAnimationFrame(frame);
}

function applyStep(i) {
  figState.step = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[figState.step];
  setModelFromName(step.state.bindingModel);
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (label) label.textContent = (figState.step + 1) + '/' + demoSteps.length + ' ' + step.title;
}

function prevStep() {
  applyStep(figState.step - 1);
}

function nextStep() {
  applyStep(figState.step + 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

