// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 980, H = 430;
draw.viewbox(0, 0, W, H);

var colors = {
  enzyme: '#c9db75',
  enzymeShade: '#e6edd0',
  enzymeEdge: '#111111',
  pocket: '#9faa46',
  substrate: '#d7c5e3',
  substrateHi: '#eadff0',
  peg: '#d7aa86',
  pegEdge: '#a67b5e',
  black: '#111111',
  text: '#202020',
  change: '#b28b31'
};

var stages = ['unbound', 'docking', 'complexFormed'];
var stageProgress = { unbound: 0, docking: 0.55, complexFormed: 1 };
var figState = { bindingStage: 'unbound', progress: 0, step: 0, animating: false };

var demoSteps = [
  {
    title: 'Compare the starting shapes',
    narration: 'Both models are visible side by side. In lock-and-key, the active site already has the proper shape; in induced fit, the active site begins more open and is labeled as changing to fit.',
    state: { bindingStage: 'unbound' }
  },
  {
    title: 'Watch substrates dock',
    narration: 'The substrates move toward the active sites in both panels. The lock-and-key pocket remains rigid, while the induced-fit pocket begins to reshape around the incoming substrates.',
    state: { bindingStage: 'docking' }
  },
  {
    title: 'Compare the formed complexes',
    narration: 'Both substrate complexes are formed, but for different reasons: one uses an unchanged preformed pocket, and the other forms a complementary pocket by conformational change.',
    state: { bindingStage: 'complexFormed' }
  }
];

function clamp01(v) {
  return Math.max(0, Math.min(1, v));
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function pt(x, y) {
  return x.toFixed(1) + ',' + y.toFixed(1);
}

function textBlock(parent, lines, x, y, size, anchor, weight) {
  if (typeof lines === 'string') lines = lines.split('\n');
  anchor = anchor || 'middle';
  var g = parent.group();
  var lineH = size * 1.12;
  for (var i = 0; i < lines.length; i++) {
    var t = g.text(lines[i]).font({
      family: 'Arial, Helvetica, sans-serif',
      size: size,
      anchor: anchor,
      weight: weight || 'normal',
      leading: 1
    }).fill(colors.text).attr({
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': 5,
      'stroke-linejoin': 'round'
    });
    if (anchor === 'middle') {
      t.center(x, y + i * lineH);
    } else if (anchor === 'end') {
      var bbe = t.bbox();
      t.move(x - bbe.width, y + i * lineH - size * 0.55);
    } else {
      t.move(x, y + i * lineH - size * 0.55);
    }
  }
  return g;
}

function arrowHead(parent, x, y, angle, size) {
  var bx = x - Math.cos(angle) * size;
  var by = y - Math.sin(angle) * size;
  var px = -Math.sin(angle) * size * 0.45;
  var py = Math.cos(angle) * size * 0.45;
  return parent.polygon([[x, y], [bx + px, by + py], [bx - px, by - py]])
    .fill(colors.black).stroke('none');
}

function straightArrow(parent, x1, y1, x2, y2, w, size) {
  parent.line(x1, y1, x2, y2)
    .stroke({ color: colors.black, width: w || 2.1, linecap: 'round' });
  arrowHead(parent, x2, y2, Math.atan2(y2 - y1, x2 - x1), size || 11);
}

function curvedArrow(parent, x1, y1, c1x, c1y, c2x, c2y, x2, y2, w, size) {
  parent.path('M ' + x1 + ' ' + y1 + ' C ' + c1x + ' ' + c1y + ' ' + c2x + ' ' + c2y + ' ' + x2 + ' ' + y2)
    .fill('none')
    .stroke({ color: colors.black, width: w || 2.1, linecap: 'round', linejoin: 'round' });
  arrowHead(parent, x2, y2, Math.atan2(y2 - c2y, x2 - c2x), size || 11);
}

function leader(parent, x1, y1, x2, y2) {
  parent.line(x1, y1, x2, y2)
    .stroke({ color: colors.black, width: 2, linecap: 'round' });
}

function pocketParams(cx, cy, p) {
  p = clamp01(p);
  return {
    lipX: lerp(48, 34, p),
    lipY: lerp(cy - 28, cy - 37, p),
    valleyY: lerp(cy - 16, cy + 5, p),
    bendX: lerp(30, 17, p)
  };
}

function enzymePath(cx, cy, pocketP) {
  var q = pocketParams(cx, cy, pocketP);
  return [
    'M', pt(cx - 96, cy + 8),
    'C', pt(cx - 101, cy - 31), pt(cx - 64, cy - 58), pt(cx - 43, cy - 39),
    'C', pt(cx - 35, cy - 32), pt(cx - q.lipX - 6, cy - 31), pt(cx - q.lipX, q.lipY),
    'C', pt(cx - q.lipX + 7, cy - 4), pt(cx - q.bendX, q.valleyY), pt(cx, q.valleyY),
    'C', pt(cx + q.bendX, q.valleyY), pt(cx + q.lipX - 7, cy - 4), pt(cx + q.lipX, q.lipY),
    'C', pt(cx + q.lipX + 6, cy - 31), pt(cx + 35, cy - 32), pt(cx + 43, cy - 39),
    'C', pt(cx + 64, cy - 58), pt(cx + 101, cy - 31), pt(cx + 96, cy + 8),
    'C', pt(cx + 106, cy + 61), pt(cx + 55, cy + 88), pt(cx, cy + 86),
    'C', pt(cx - 55, cy + 88), pt(cx - 106, cy + 61), pt(cx - 96, cy + 8),
    'Z'
  ].join(' ');
}

function pocketStrokePath(cx, cy, pocketP) {
  var q = pocketParams(cx, cy, pocketP);
  return [
    'M', pt(cx - q.lipX, q.lipY),
    'C', pt(cx - q.lipX + 7, cy - 4), pt(cx - q.bendX, q.valleyY), pt(cx, q.valleyY),
    'C', pt(cx + q.bendX, q.valleyY), pt(cx + q.lipX - 7, cy - 4), pt(cx + q.lipX, q.lipY)
  ].join(' ');
}

function enzymeHighlightPath(cx, cy) {
  return [
    'M', pt(cx - 70, cy + 34),
    'C', pt(cx - 44, cy + 67), pt(cx + 44, cy + 67), pt(cx + 70, cy + 34),
    'C', pt(cx + 44, cy + 91), pt(cx - 44, cy + 91), pt(cx - 70, cy + 34),
    'Z'
  ].join(' ');
}

function drawEnzyme(parent, cx, cy, model, pocketP, highlightChange) {
  var g = parent.group();
  var body = g.path(enzymePath(cx, cy, pocketP))
    .fill(colors.enzyme)
    .stroke({ color: colors.enzymeEdge, width: 3, linejoin: 'round' });

  g.path(enzymeHighlightPath(cx, cy))
    .fill(colors.enzymeShade)
    .stroke('none')
    .opacity(0.72);

  g.path(pocketStrokePath(cx, cy, pocketP))
    .fill('none')
    .stroke({
      color: highlightChange ? colors.change : colors.pocket,
      width: highlightChange ? 5 : 4,
      linecap: 'round',
      linejoin: 'round',
      opacity: highlightChange ? 0.72 : 0.55
    });

  body.on('mousemove', function (e) {
    showTooltip(model === 'lock'
      ? 'Lock-and-key: this active site keeps the same complementary shape.'
      : 'Induced fit: the central active site changes shape during binding.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup(model === 'lock' ? 'Lock-and-key model' : 'Induced-fit model',
      model === 'lock'
        ? 'The lock-and-key active site is already complementary to the substrates. Binding forms a complex without requiring the enzyme pocket to reshape.'
        : 'The induced-fit active site begins more open. As the substrates bind, the enzyme changes conformation so the pocket becomes complementary.');
  }).css('cursor', 'pointer');

  return g;
}

function substratePiecePath(innerX, y, side) {
  var s = side === 'right' ? 1 : -1;
  function X(d) { return innerX + s * d; }
  return [
    'M', pt(innerX, y + 7),
    'L', pt(innerX, y + 78),
    'L', pt(X(13), y + 78),
    'L', pt(X(13), y + 62),
    'C', pt(X(36), y + 62), pt(X(49), y + 48), pt(X(49), y + 29),
    'C', pt(X(49), y + 11), pt(X(31), y - 4), pt(X(12), y),
    'C', pt(X(-2), y + 3), pt(X(-3), y + 6), pt(innerX, y + 7),
    'Z'
  ].join(' ');
}

function substrateHighlightPath(innerX, y, side) {
  var s = side === 'right' ? 1 : -1;
  function X(d) { return innerX + s * d; }
  return [
    'M', pt(X(10), y + 9),
    'C', pt(X(27), y + 7), pt(X(39), y + 19), pt(X(38), y + 33),
    'C', pt(X(37), y + 48), pt(X(24), y + 55), pt(X(14), y + 56),
    'L', pt(X(14), y + 76),
    'L', pt(X(6), y + 76),
    'L', pt(X(6), y + 14),
    'C', pt(X(6), y + 11), pt(X(8), y + 10), pt(X(10), y + 9),
    'Z'
  ].join(' ');
}

function drawSubstratePiece(parent, innerX, y, side) {
  var g = parent.group();
  var s = side === 'right' ? 1 : -1;
  var pegX = side === 'right' ? innerX + 8 : innerX - 22;

  g.rect(15, 25).radius(4)
    .move(pegX, y + 72)
    .fill(colors.peg)
    .stroke({ color: colors.pegEdge, width: 1.1 });

  var blob = g.path(substratePiecePath(innerX, y, side))
    .fill(colors.substrate)
    .stroke({ color: colors.black, width: 2.7, linejoin: 'round' });

  g.path(substrateHighlightPath(innerX, y, side))
    .fill(colors.substrateHi)
    .stroke('none')
    .opacity(0.72);

  blob.on('mousemove', function (e) {
    showTooltip('Substrate piece: its shape must match the enzyme active site.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup('Substrates', 'The purple pieces represent substrates. In both models, compatible substrates end in the enzyme active site as an enzyme-substrate complex.');
  }).css('cursor', 'pointer');

  return g;
}

function drawSubstratePair(parent, cx, topY, gap) {
  var g = parent.group();
  drawSubstratePiece(g, cx - gap, topY, 'left');
  drawSubstratePiece(g, cx + gap, topY, 'right');
  return g;
}

