function ease(t) {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

function setStage(stage, animate) {
  if (stages.indexOf(stage) < 0) stage = 'unbound';
  figState.bindingStage = stage;
  var target = stageProgress[stage];

  if (!animate) {
    figState.progress = target;
    drawFigure();
    return;
  }

  if (figState.animating) return;
  figState.animating = true;
  var start = figState.progress;
  var t0 = performance.now();
  var dur = 700 + Math.abs(target - start) * 600;

  function frame(now) {
    var k = Math.min(1, (now - t0) / dur);
    figState.progress = lerp(start, target, ease(k));
    drawFigure();
    if (k < 1) {
      requestAnimationFrame(frame);
    } else {
      figState.progress = target;
      figState.animating = false;
      drawFigure();
    }
  }
  requestAnimationFrame(frame);
}

